constants:
CoordScriptRunner — 좌표 기반 사냥 스크립트 실행기
행동(action) 리스트를 순서대로 실행합니다.

action 형식:
  공격: {"type": "attack", "x": 20, "direction": "left", "attack_mode": "duration"|"count", "attack_value": 10}
  이동: {"type": "move", "x": 35, "move_type": "walk"|"teleport", "direction": "left"|"right"}

QLineEdit {
    background-color: #FFF5F5;
    border: 2px solid #FC8181;
    border-radius: 6px;
    padding: 4px 10px;
    color: #1A365D;
    font-weight: bold;
    font-size: 11pt;
}
QLineEdit:focus { border-color: #C53030; }

/* ── 기본 배경 ── */
QMainWindow, QWidget {
    background-color: #F5F7FA;
    color: #2D3748;
    font-family: '맑은 고딕';
    font-size: 9pt;
}

/* ── 탭 위젯 ── */
QTabWidget::pane {
    border: 1px solid #CBD5E0;
    border-radius: 6px;
    background-color: #FFFFFF;
    top: -1px;
}
QTabBar::tab {
    background-color: #EDF2F7;
    color: #718096;
    border: 1px solid #CBD5E0;
    border-bottom: none;
    padding: 7px 18px;
    margin-right: 2px;
    border-top-left-radius: 6px;
    border-top-right-radius: 6px;
    font-weight: bold;
}
QTabBar::tab:selected {
    background-color: #FFFFFF;
    color: #2196F3;
    border-bottom: 2px solid #FFFFFF;
}
QTabBar::tab:hover:!selected {
    background-color: #E2E8F0;
    color: #4A5568;
}

/* ── 그룹박스 ── */
QGroupBox {
    background-color: #FFFFFF;
    border: 1px solid #CBD5E0;
    border-radius: 8px;
    margin-top: 12px;
    padding-top: 8px;
    font-weight: bold;
    color: #4A5568;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    left: 12px;
    top: -1px;
    padding: 0 6px;
    background-color: #FFFFFF;
    color: #2196F3;
    font-size: 9pt;
}

/* ── 버튼 ── */
QPushButton {
    background-color: #FFFFFF;
    color: #4A5568;
    border: 1px solid #CBD5E0;
    border-radius: 6px;
    padding: 5px 12px;
    font-weight: bold;
}
QPushButton:hover {
    background-color: #EBF8FF;
    border-color: #2196F3;
    color: #2196F3;
}
QPushButton:pressed {
    background-color: #BEE3F8;
}
QPushButton:disabled {
    background-color: #EDF2F7;
    color: #A0AEC0;
    border-color: #E2E8F0;
}
QPushButton:checked {
    background-color: #2196F3;
    color: #FFFFFF;
    border-color: #1976D2;
}

/* ── 하단 주요 버튼 (높이 40px 버튼들) ── */
QPushButton#btn_start {
    background-color: #48BB78;
    color: #FFFFFF;
    border: none;
    font-size: 10pt;
}
QPushButton#btn_start:hover  { background-color: #38A169; }
QPushButton#btn_start:disabled { background-color: #9AE6B4; }

QPushButton#btn_stop {
    background-color: #FC8181;
    color: #FFFFFF;
    border: none;
    font-size: 10pt;
}
QPushButton#btn_stop:hover  { background-color: #E53E3E; }
QPushButton#btn_stop:disabled { background-color: #FEB2B2; }

QPushButton#btn_pause {
    background-color: #F6AD55;
    color: #FFFFFF;
    border: none;
    font-size: 10pt;
}
QPushButton#btn_pause:hover  { background-color: #DD6B20; }
QPushButton#btn_pause:disabled { background-color: #FBD38D; }

QPushButton#btn_save {
    background-color: #2196F3;
    color: #FFFFFF;
    border: none;
    font-size: 10pt;
}
QPushButton#btn_save:hover  { background-color: #1976D2; }
QPushButton#btn_save:disabled { background-color: #90CAF9; }

/* ── 입력 필드 ── */
QLineEdit, QSpinBox {
    background-color: #FFFFFF;
    border: 1px solid #CBD5E0;
    border-radius: 5px;
    padding: 4px 8px;
    color: #2D3748;
}
QLineEdit:focus, QSpinBox:focus {
    border-color: #2196F3;
}
QLineEdit:disabled {
    background-color: #EDF2F7;
    color: #A0AEC0;
}

/* ── 콤보박스 ── */
QComboBox {
    background-color: #FFFFFF;
    border: 1px solid #CBD5E0;
    border-radius: 5px;
    padding: 4px 8px;
    padding-right: 24px;
    color: #2D3748;
}
QComboBox:focus {
    border-color: #2196F3;
}
QComboBox QAbstractItemView {
    background-color: #FFFFFF;
    border: 1px solid #CBD5E0;
    border-radius: 4px;
    selection-background-color: #EBF8FF;
    selection-color: #2196F3;
}

/* ── 체크박스 ── */
QCheckBox {
    spacing: 6px;
    color: #2D3748;
}
QCheckBox::indicator {
    width: 16px;
    height: 16px;
    border: 1px solid #CBD5E0;
    border-radius: 3px;
    background-color: #FFFFFF;
}
QCheckBox::indicator:checked {
    background-color: #2196F3;
    border-color: #2196F3;
}

/* ── 테이블 ── */
QTableWidget {
    background-color: #FFFFFF;
    border: 1px solid #CBD5E0;
    border-radius: 6px;
    gridline-color: #EDF2F7;
}
QTableWidget::item:selected {
    background-color: #EBF8FF;
    color: #2196F3;
}
QHeaderView::section {
    background-color: #EDF2F7;
    color: #4A5568;
    border: none;
    border-right: 1px solid #CBD5E0;
    border-bottom: 1px solid #CBD5E0;
    padding: 5px 8px;
    font-weight: bold;
}

/* ── 스크롤바 ── */
QScrollBar:vertical {
    background: #F5F7FA;
    width: 8px;
    border-radius: 4px;
}
QScrollBar::handle:vertical {
    background: #CBD5E0;
    border-radius: 4px;
    min-height: 30px;
}
QScrollBar::handle:vertical:hover { background: #A0AEC0; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; }

QScrollBar:horizontal {
    background: #F5F7FA;
    height: 8px;
    border-radius: 4px;
}
QScrollBar::handle:horizontal {
    background: #CBD5E0;
    border-radius: 4px;
    min-width: 30px;
}
QScrollBar::handle:horizontal:hover { background: #A0AEC0; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; }

/* ── 상태바 ── */
QStatusBar {
    background-color: #EDF2F7;
    border-top: 1px solid #CBD5E0;
    color: #4A5568;
    font-size: 8pt;
}

/* ── 스크롤에리어 ── */
QScrollArea {
    border: none;
    background-color: transparent;
}

QComboBox {
    background-color: #FFFFFF;
    border: 2px solid #2196F3;
    border-radius: 6px;
    padding: 4px 12px;
    padding-right: 28px;
    color: #1A365D;
    font-weight: bold;
    font-size: 11pt;
}
QComboBox:hover { border-color: #1976D2; background-color: #EBF8FF; }
QComboBox::drop-down { width: 24px; border: none; }
QComboBox QAbstractItemView {
    background-color: #FFFFFF;
    border: 2px solid #2196F3;
    selection-background-color: #BBDEFB;
    selection-color: #0D47A1;
    font-size: 11pt;
    font-weight: bold;
}

QLineEdit {
    background-color: #FFF5F5;
    border: 2px solid #FC8181;
    border-radius: 6px;
    padding: 4px 10px;
    color: #1A365D;
    font-weight: bold;
    font-size: 9pt;
}
QLineEdit:focus { border-color: #C53030; }
